  function send_bulk_email_pemenuhan()
  {
    if (!$this->ion_auth->ceklogin()) {
      $this->session->set_flashdata('title', 'Login Gagal');
      $this->session->set_flashdata('text', 'Anda Tidak Memiliki Akses, Silahkan Login Dahulu');
      $this->session->set_flashdata('class', "warning");
      redirect('login', 'refresh');
    }
    $record = $this->Bu_model->get_email_pemenuhan_lpjk();
    foreach ($record as $row) {
      $this->send_pemenuhan($row['email'],$row['id_izin'],$row['nama_bu'],$row['nama_tkk'],$row['pjt'],$row['noreg'],$row['tipe']);
      $this->Bu_model->update_pemenuhan_email_lpjk($row['id']);
    }
    echo "Done";
  }
    function send_pemenuhan($email,$id_izin,$nama_bu,$nama_tkk,$pjt,$noreg,$tipe)
  {
    if (!$this->ion_auth->ceklogin()) {
      $this->session->set_flashdata('title', 'Login Gagal');
      $this->session->set_flashdata('text', 'Anda Tidak Memiliki Akses, Silahkan Login Dahulu');
      $this->session->set_flashdata('class', "warning");
      redirect('login', 'refresh');
    }
    $this->load->config('email');
    $this->load->library('email');
    if($pjt=='1'){
      $tenaga_kerja="PJTBU";
    }else{
      $tenaga_kerja="PJSKBU";
    }
    if($tipe=='1'){
      $tipe_kosong="SKK HABIS MASA BERLAKU";
    }else{
      $tipe_kosong="SKK DICABUT LSP";
    }
    
    $message = $this->notif_email_pemenuhan($id_izin,$nama_bu,$nama_tkk,$noreg,$tenaga_kerja,$tipe_kosong);
    // $message="<b>aaaa</b>";
    $this->email->set_newline("\r\n");
    $this->email->from('survailen@lsbugapeknas.com', 'LSBU GAPEKNAS');
    $this->email->to($email);
    $this->email->subject('Surat Peringatan Terkait Pemenuhan Persyaratan Tenaga Kerja SBU');
    $this->email->message($message);
    $this->email->cc("pt.lsbugapeknas21@gmail.com, ccgapeknas@gmail.com");

    if ($this->email->send()) {
      return "Success";
    } else {
      return "Failed";
    }
  }

