  function pelaporan_penilaian_lpjk($id1, $id2)
  {

    $tgl = decrypt_url($id2);
    $nib = decrypt_url($id1);
    $klasifikasi = $this->Bu_model->klasifikasi_kualifikasi_oprx_sub_klasifikasi($nib, $tgl);
    $tgl_permohonan = $klasifikasi[0]['tgl_permohonan'];
    $asesor = $this->Bu_model->cek_pilih_asesor2($nib, $tgl_permohonan);
    $sub_klasifikasi = $klasifikasi[0]['id_sub_klasifikasi'];
    $id_izin = $klasifikasi[0]['id_izin'];
    $id_user = $this->session->userdata('id_user');

    $this->data = array(
      'asesor' => $asesor,
      'biodata' => $this->Bu_model->biodata_opr($nib),
      'klasifikasi' => $klasifikasi,

      'id1' => $id1,
      'id2' => $id2,
      'id3' => $id3
    );
    $this->load->view('sertifikasi/pelaporan_penilaian_lpjk', $this->data);
    //$this->template->load('menu/menu', 'sertifikasi/pelaporan_penilaian_lpjk', $this->data);

  }
