  function surat_tugas_the($id1, $id2)
  {
    if (!$this->ion_auth->ceklogin()) {
      $this->session->set_flashdata('title', 'Login Gagal');
      $this->session->set_flashdata('text', 'Anda Tidak Memiliki Akses, Silahkan Login Dahulu');
      $this->session->set_flashdata('class', "warning");
      redirect('login', 'refresh');
    }

    $this->load->library('pdfgenerator');


    $nib = decrypt_url($id1);
    $tgl_permohonan = decrypt_url($id2);


    $tahun = date("Y-m-d");
    $bulan_romawi = $this->getBulanrw(date("m"));
    $bulan_huruf = $this->getBulan(date("m"));

    $reco2xc = $this->Bu_model->get_penunjukan_the($nib, $tgl_permohonan);
    $id_user = $reco2xc[0]['id_komite'];
    $reco2 = $this->Bu_model->get_surat_tugas_the($nib, $tgl_permohonan);
    $recx = $this->Bu_model->check_permohonan($nib, $tgl_permohonan);

    $rec = $recx;

    $recmn = $this->Bu_model->klasifikasi_kualifikasi_opr($nib, $tgl_permohonan);

    $record = $this->Bu_model->biodata_opr($nib);
    $aso = trim($recmn[0]['asosiasi']);
    $data = array(
      'bulan' => $bulan_huruf,
      'izin' => $recmn,
      'asosiasi' => $this->Bu_model->get_asosiasi($aso),
      'user' => $this->Bu_model->get_user($id_user),
      'history' => $rec,
      'bu' => $record,
      'id_user' => $id_user,
      'no_surat' => $no_surat,
      'tgl_permohonan' => $tgl_permohonan,
      'asesor' => $this->Bu_model->cek_pilih_asesor2($nib, $tgl_permohonan)
    );

    $html = $this->load->view('sertifikasi/surat_tugas_the', $data, true);
    $filename = 'Surat_Tugas_' . $no_surat;
    $dr = $this->Bu_model->get_asosiasi($aso);
    $this->pdfgenerator->generate($html, $filename, true, 'A4', 'portrait');
  }
  function fthep($id1, $id2, $id3)
  {
    if (!$this->ion_auth->ceklogin()) {
      $this->session->set_flashdata('title', 'Login Gagal');
      $this->session->set_flashdata('text', 'Anda Tidak Memiliki Akses, Silahkan Login Dahulu');
      $this->session->set_flashdata('class', "warning");
      redirect('login', 'refresh');
    }
    $tgl = decrypt_url($id2);
    $nib = decrypt_url($id1);
    $id_user = decrypt_url($id3);

    $klasifikasi = $this->Bu_model->klasifikasi_kualifikasi_oprx_sub_klasifikasi($nib, $tgl);
    $sub_klasifikasi = $klasifikasi[0]['id_sub_klasifikasi'];
    $id_izin = $klasifikasi[0]['id_izin'];
    $fthep = $this->Bu_model->penilaian_fthep($id_izin, $id_user);
    $tgl_penilaian = $fthep[0]['tgl_penilaian'];
    $bulan =  date("m", strtotime($tgl_penilaian));
    $tanggal =  date("d", strtotime($tgl_penilaian));
    $tahun =  date("Y", strtotime($tgl_penilaian));

    $this->load->library('pdfgenerator');
    $tgl_permohonan = $klasifikasi[0]['tgl_permohonan'];
    $id3 = encrypt_url($id_user);
    $asesor = $this->Bu_model->cek_pilih_asesor2($nib, $tgl_permohonan);
    $this->data = array(
      'tanggal' => $tanggal,
      'bulan' => $this->getBulan($bulan),
      'tahun' => $tahun,
