  function insert_penilaian_frpkp()
  {
    if (!$this->ion_auth->ceklogin()) {
      $this->session->set_flashdata('title', 'Login Gagal');
      $this->session->set_flashdata('text', 'Anda Tidak Memiliki Akses, Silahkan Login Dahulu');
      $this->session->set_flashdata('class', "warning");
      redirect('login', 'refresh');
    }
    $post = $this->input->post();
    $id_izin = $this->security->xss_clean(trim($post['id_izin']));
    $record = $this->Bu_model->klasifikasi_kualifikasi_oprx_izin($id_izin);
    $nib = $record[0]['NIB'];
    $id_sub_klasifikasi = $record[0]['id_sub_klasifikasi'];
    $id1 = $this->security->xss_clean(trim($post['id1']));
    $id2 = $this->security->xss_clean(trim($post['id2']));
    $id3 = $this->security->xss_clean(trim($post['id3']));
    $id_user = $this->session->userdata('id_user');

    $catatan = $this->security->xss_clean(trim($post['catatan_frpkp']));
    $checkbox_keuangan = $this->security->xss_clean(trim($post['checkbox_keuangan']));
    $checkbox_tk = $this->security->xss_clean(trim($post['checkbox_tk']));
    $checkbox_penjualan_tahunan = $this->security->xss_clean(trim($post['checkbox_tk']));
    $checkbox_peralatan = $this->security->xss_clean(trim($post['checkbox_peralatan']));
    $checkbox_smap = $this->security->xss_clean(trim($post['checkbox_smap']));
    if ($checkbox_keuangan == '1' and $checkbox_tk == '1' and $checkbox_penjualan_tahunan == '1' and $checkbox_peralatan == '1' and $checkbox_smap == '1') {
      $checkbox = '1';
    } else {
      $checkbox = '0';
    }

    $nilai_penjualan_tahunan = $this->security->xss_clean(trim($post['nilai_penjualan_tahunan']));
    $nilai_keuangan = $this->security->xss_clean(trim($post['nilai_keuangan']));
    $komitmen_peralatan = $this->security->xss_clean(trim($post['komitmen_peralatan']));
    $nomor_sertifikat_iso = $this->security->xss_clean(trim($post['nomor_sertifikat_iso']));
    $penerbit_iso = $this->security->xss_clean(trim($post['penerbit_iso']));
    $nilai_pancek = $this->security->xss_clean(trim($post['nilai_pancek']));
    $pemenuhan_dokumen_smap = $this->security->xss_clean(trim($post['pemenuhan_dokumen_smap']));
    $sub_klas_pjtbu = $this->security->xss_clean(trim($post['sub_klas_pjtbu']));
    $jenjang_pjtbu = $this->security->xss_clean(trim($post['jenjang_pjtbu']));
    $sub_klas_pjskbu = $this->security->xss_clean(trim($post['sub_klas_pjskbu']));
    $jenjang_pjskbu = $this->security->xss_clean(trim($post['jenjang_pjskbu']));
    $tahun_smap = $this->security->xss_clean(trim($post['tahun_smap']));
    $persyaratan_keuangan = $this->security->xss_clean(trim($post['persyaratan_keuangan']));
    $persyaratan_penjualan_tahunan = $this->security->xss_clean(trim($post['persyaratan_penjualan_tahunan']));
    $tgl_permohonan = $record[0]['tgl_permohonan'];
    $klasifikasi = $record[0]['id_klasifikasi'];
    $sub_klas = $record[0]['id_sub_klasifikasi'];
    $kualifikasi = $record[0]['kualifikasi'];
    $select = "REPLACE INTO lsbu_asesor_penilaian (NIB,tgl_permohonan,id_asesor,id_klasifikasi,id_sub_klasifikasi,kualifikasi,hasil_akhir,kd,aset,tk,peralatan,penjualan_tahunan,smm,smap,comment,nilai_penjualan_tahunan,nilai_kemampuan_keuangan,komitmen_sewa,no_sertifikat_smap,penerbit_smap,nilai_pancek,pemenuhan_dokumen_smap,sub_klas_pjtbu,jenjang_pjtbu,sub_klas_pjskbu,jenjang_pjskbu,tahun_smap,persyaratan_penjualan_tahunan,persyaratan_keuangan) VALUES ('$nib','$tgl_permohonan','$id_user','$klasifikasi','$sub_klas','$kualifikasi',$checkbox,'0',$checkbox_keuangan,$checkbox_tk,$checkbox_penjualan_tahunan,$checkbox_peralatan,'1',$checkbox_smap,'$catatan','$nilai_penjualan_tahunan','$nilai_keuangan','$komitmen_peralatan','$nomor_sertifikat_iso','$penerbit_iso','$nilai_pancek','$pemenuhan_dokumen_smap','$sub_klas_pjtbu','$jenjang_pjtbu','$sub_klas_pjskbu','$jenjang_pjskbu','$tahun_smap','$persyaratan_penjualan_tahunan','$persyaratan_keuangan')";
    $where = "";
    $insert = $this->Bu_model->delete_opr($select, $where);

    $this->session->set_flashdata('title', 'Success');
    $this->session->set_flashdata('text', 'Penilaian Form FRPKP berhassil disimpan');
    $this->session->set_flashdata('class', "success");
    redirect('sertifikasi/penilaian_frpkp/' . $id1 . '/' . $id2 . '/' . $id3, 'refresh');
  }
