      $catatan_keuangan = $this->security->xss_clean(trim($post['catatan_keuangan' . $sub_klasifikasi]));
      $checkbox_tk = $this->security->xss_clean(trim($post['checkbox_tk' . $sub_klasifikasi]));
      $catatan_tk = $this->security->xss_clean(trim($post['catatan_tk' . $sub_klasifikasi]));

      $checkbox_penjualan_tahunan = $this->security->xss_clean(trim($post['checkbox_penjualan_tahunan' . $sub_klasifikasi]));
      $catatan_penjualan_tahunan = $this->security->xss_clean(trim($post['catatan_penjualan_tahunan' . $sub_klasifikasi]));

      $checkbox_peralatan = $this->security->xss_clean(trim($post['checkbox_peralatan' . $sub_klasifikasi]));
      $catatan_peralatan = $this->security->xss_clean(trim($post['catatan_peralatan' . $sub_klasifikasi]));

      $checkbox_smap = $this->security->xss_clean(trim($post['checkbox_smap' . $sub_klasifikasi]));
      $catatan_smap = $this->security->xss_clean(trim($post['catatan_smap' . $sub_klasifikasi]));

      if ($checkbox_keuangan == '1' and $checkbox_tk == '1' and $checkbox_penjualan_tahunan == '1' and $checkbox_peralatan == '1' and $checkbox_smap == '1') {
        $checkbox = '1';
      } else {
        $checkbox = '0';
      }

      $nilai_penjualan_tahunan = $this->security->xss_clean(trim($post['nilai_penjualan_tahunan' . $sub_klasifikasi]));
      $nilai_keuangan = $this->security->xss_clean(trim($post['nilai_keuangan' . $sub_klasifikasi]));
      $komitmen_peralatan = $this->security->xss_clean(trim($post['komitmen_peralatan' . $sub_klasifikasi]));
      $nomor_sertifikat_iso = $this->security->xss_clean(trim($post['nomor_sertifikat_iso' . $sub_klasifikasi]));
