      $select = "REPLACE INTO lsbu_tinjauan_hasil_evaluasi (NIB,id_izin,tgl_permohonan,id_asesor,id_sub_klasifikasi,kualifikasi,hasil_akhir,aset,catatan_aset,peralatan,catatan_peralatan,tk,catatan_tk,penjualan_tahunan,catatan_penjualan_tahunan,smm,smap,catatan_smap,comment,nilai_penjualan_tahunan,nilai_kemampuan_keuangan,komitmen_sewa,no_sertifikat_smap,penerbit_smap,nilai_pancek,pemenuhan_dokumen_smap,sub_klas_pjtbu,jenjang_pjtbu,sub_klas_pjskbu,jenjang_pjskbu) VALUES ('$nib','$id_izin','$tgl_permohonan','$id_user','$sub_klas','$kualifikasi',$checkbox,$checkbox_keuangan,'$catatan_keuangan',$checkbox_peralatan,'$catatan_peralatan',$checkbox_tk,'$catatan_tk',$checkbox_penjualan_tahunan,'$catatan_penjualan_tahunan','1',$checkbox_smap,'$catatan_smap','$catatan','$nilai_penjualan_tahunan','$nilai_keuangan','$komitmen_peralatan','$nomor_sertifikat_iso','$penerbit_iso','$nilai_pancek','$pemenuhan_dokumen_smap','$sub_klas_pjtbu','$jenjang_pjtbu','$sub_klas_pjskbu','$jenjang_pjskbu')";
      $where = "";
      $insert = $this->Bu_model->delete_opr($select, $where);
    }


    $this->session->set_flashdata('title', 'Success');
