  function list_report()
  {
    if (!$this->ion_auth->ceklogin()) {
      $this->session->set_flashdata('title', 'Login Gagal');
      $this->session->set_flashdata('text', 'Anda Tidak Memiliki Akses, Silahkan Login Dahulu');
      $this->session->set_flashdata('class', "warning");
      redirect('login', 'refresh');
    } elseif ($this->ion_auth->admin_pusat()) {
      $record = $this->Bu_model->list_report();

      $data = array();
      foreach ($record as $row) {
        $bulan = date("m", strtotime($row['tgl_permohonan']));
        $tanggal = date("d", strtotime($row['tgl_permohonan']));
        $tahuun = date("Y", strtotime($row['tgl_permohonan']));
        $bulan_romawi = $this->getBulanrw($bulan);
        $bulan_huruf = $this->getBulan($bulan);
        $panjang = strlen($row['no_urut']);
        $jumlah = 5 - $panjang;
        $nol = '';
        for ($i = 0; $i < $jumlah; $i++) {
          $nol = $nol . '0';
        }
        $nomor_urut = $nol . $row['no_urut'] . '/Perjanjian/' . $bulan_romawi . '/' . $tahuun;
        $nomor_urut_full = "DOKUMEN PERJANJIAN SERTIFIKASI NOMOR :" . $nol . $row['no_urut'] . '/Perjanjian/' . $bulan_romawi . '/2022 Tanggal ' . $tanggal . ' ' . $bulan_huruf . ' ' . $tahuun;
        if ($row['klasifikasi_jenis_usaha'] == "1") {
          $klasifikasi_jenis = "BUJKN";
        } else if ($row['klasifikasi_jenis_usaha'] == "2") {
          $klasifikasi_jenis = "BUJKPMA";
        } else if ($row['klasifikasi_jenis_usaha'] == "3") {
          $klasifikasi_jenis = "BUJKA";
        } else {
          $klasifikasi_jenis = "";
        }
        $x = array(
          'nama_propinsi' => $row['nama_propinsi'],
          'jenis_usaha' => $klasifikasi_jenis,
          'bentuk_usaha' => $row['bentuk_usaha'],
          'nama_kabupaten' => $row['nama_kabupaten'],
          'id_izin' => $row['id_izin'],
          'file_perjanjian' => $row['file_perjanjian'],
          'npwp' => $row['npwp'],
          'id_sub_klasifikasi' => $row['id_sub_klasifikasi'],
          'kualifikasi' => $row['kualifikasi'],
          'tgl_permohonan' => $row['tgl_permohonan'],
          'nomor_urut' => $row['nomor_urut'],
          'NIB' => $row['NIB'],
          'nama' => $row['nama'],
          'alamat_bu' => $row['alamat_bu'],
          'nomor_kbli' => $row['nomor_kbli'],
          'nomor_urut' => $nomor_urut,
          'nomor_urut_full' => $nomor_urut_full
        );
        array_push($data, $x);
      }
      $object = new PHPExcel();

      $object->setActiveSheetIndex(0);

      $table_columns = array(
        "id_izin",
        "NIB",
        "nama",
        "jenis",
        "npwp",
        "id_sub_klasifikasi",
        "kualifikasi",
        "alamat_bu",
        "bentuk",
        "nama_propinsi",
        "nama_kabupaten",
        "nomor_kbli",
        "nomor_sps",
        "deskripsi_sps",
        "tgl_permohonan",
        "file_perjanjian"
      );
      $column = 0;

      foreach ($table_columns as $field) {

        $object->getActiveSheet()->setCellValueByColumnAndRow($column, 1, $field);

        $column++;
      }

      $excel_row = 2;
      foreach ($data as $row) {
        $object->getActiveSheet()->setCellValueByColumnAndRow(0, $excel_row, $row['id_izin']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(1, $excel_row, "'" . $row['NIB']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(2, $excel_row, $row['nama']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(3, $excel_row, $row['jenis_usaha']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(4, $excel_row, "'" . $row['npwp']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(5, $excel_row, $row['id_sub_klasifikasi']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(6, $excel_row, $row['kualifikasi']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(7, $excel_row, $row['alamat_bu']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(8, $excel_row, $row['bentuk_usaha']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(9, $excel_row, $row['nama_propinsi']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(10, $excel_row, $row['nama_kabupaten']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(11, $excel_row, $row['nomor_kbli']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(12, $excel_row, $row['nomor_urut']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(13, $excel_row, $row['nomor_urut_full']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(14, $excel_row, $row['tgl_permohonan']);
        $object->getActiveSheet()->setCellValueByColumnAndRow(15, $excel_row, 'https://sertifikasi.lsbugapeknas.com/get_file/get_bu_perjanjian/' . $row['file_perjanjian']);
        $excel_row++;
      }
      $object_writer = PHPExcel_IOFactory::createWriter($object, 'Excel5');
      $filename = "Rekap_permohonan.xls";
      ob_end_clean();
      header("Content-type: application/vnd.ms-excel");
      header('Content-Disposition: attachment;filename=' . $filename . ' ');
      header("Pragma: no-cache");
      header("Expires: 0");
      $object_writer->save('php://output');
      ob_end_clean();
    }
  }
  function tinjauan_permohonan_izin($id1, $id2, $id_izin)
  {
    if (!$this->ion_auth->ceklogin()) {
      $this->session->set_flashdata('title', 'Login Gagal');
      $this->session->set_flashdata('text', 'Anda Tidak Memiliki Akses, Silahkan Login Dahulu');
      $this->session->set_flashdata('class', "warning");
      redirect('login', 'refresh');
    } elseif ($this->ion_auth->admin_pusat() or $this->ion_auth->admin_cabut() or $this->ion_auth->mitra()) {
      $tgl = decrypt_url($id2);
      $nib = decrypt_url($id1);
      $data = array();

      //$data = $this->check_pjt_pjsk($id1, $id2);
      $data = array();
      $biodata = $this->Bu_model->biodata_opr_izin($id_izin);
      if (empty($biodata)) {
        $this->get_izin($id_izin);
        $biodata = $this->Bu_model->biodata_opr_izin($id_izin);
      }
      $klasifikasi = $this->Bu_model->klasifikasi_kualifikasi_izin($id_izin);
      $this->data = array(
        'tgl' => $tgl,
        'biodata' => $biodata,
        'pengurus' => $this->Bu_model->pengurus_opr_izin($id_izin),
        'penjualan_tahunan' => $this->Bu_model->pengalaman_opr_izin($id_izin),
        'akte' => $this->Bu_model->akte_opr_izin($id_izin),
        'smm' => $this->Bu_model->smm_opr_izin($id_izin),
        'smap' => $this->Bu_model->smap_opr_izin($id_izin),
        'neraca' => $this->Bu_model->neraca_ski_izin($id_izin),
        'pemegang_saham' => $this->Bu_model->pemegang_saham_opr_izin($id_izin),
        'pjbu' => $this->Bu_model->pjbu_opr_sub_izin($id_izin),
        'pjskbu' => $this->Bu_model->pjskbu_opr_sub_izin($id_izin),
        'pjtbu' => $this->Bu_model->pjtbu_opr_sub_izin($id_izin),
        'data_check' => $data,
        'klasifikasi' => $klasifikasi,
        'notif' => $this->Bu_model->notif_opr($nib, $tgl),
        'nib_dec' => $id1,
        'tgl_dec' => $id2,
        'cek' => $this->Bu_model->cek_status_1($nib, $tgl)
      );
      $this->template->load('menu/menu', 'sertifikasi/tinjauan_permohonan_izin', $this->data);
    } else {
      $this->session->set_flashdata('title', 'Warning');
      $this->session->set_flashdata('text', 'Anda tidak memiliki akses');
      $this->session->set_flashdata('class', "warning");
      redirect('login', 'refresh');
    }
