    } elseif ($this->ion_auth->admin_pusat() or $this->ion_auth->koordinator_keuangan() or $this->ion_auth->admin_get()) {
      $data = $this->Bu_model->list_biaya_pembayaran_perpanjangan();
      $record = array();
      foreach ($data as $row) {
        $get = $this->Bu_model->get_revisi($row['NIB'], $row['tgl_permohonan']);
        if (empty($get)) {
          $status = "0";
        } else {
          foreach ($get as $row_revisi) {
            if ($row_revisi['status'] == '0') {
