  function create_qr()
  {
    if (!$this->ion_auth->ceklogin()) {
      $this->session->set_flashdata('title', 'Login Gagal');
      $this->session->set_flashdata('text', 'Anda Tidak Memiliki Akses, Silahkan Login Dahulu');
      $this->session->set_flashdata('class', "warning");
      redirect('login', 'refresh');
    }
    $post = $this->input->post();
    $nib = $this->security->xss_clean(trim($post['nib']));
    $tgl_permohonan = $this->security->xss_clean(trim($post['tgl_permohonan']));

    $record = $this->Bu_model->token_api_siki();
    $token = $record[0]['token'];
    $recx = $this->Bu_model->check_permohonan($nib, $tgl_permohonan);
    $tgl_biaya = $recx[0]['tgl_biaya'];
    $tomorrow = strtotime($tgl_biaya . " +4 hours");
    $sx = date('Y-m-d H:i:s');
    $nowx = strtotime($sx);
    if ($nowx >= $tomorrow) {

      $record = $this->Bu_model->get_permohonan_masuk($nib, $tgl_permohonan);
      foreach ($record as $row) {
        $id_izin = $row['id_izin'];

        $url = "https://siki.pu.go.id/siki-api/v1/qr-sbu/$id_izin";
        $curl = curl_init($url);
        curl_setopt($curl, CURLOPT_CUSTOMREQUEST, "GET");
        curl_setopt($curl, CURLOPT_HEADER, false);
        curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
        //curl_setopt($curl, CURLOPT_POSTFIELDS, $data);post
        curl_setopt($curl, CURLOPT_HTTPHEADER, array(
          "Content-type: application/json",
          "token: $token"
        ));

        $json_response = curl_exec($curl);
        $status = curl_getinfo($curl, CURLINFO_HTTP_CODE);
        $responses = json_decode($json_response, true);
        if ($status != 200) {
          die("Error: call to URL $url failed with status $status, response $json_response, curl_error " . curl_error($curl) . ", curl_errno " . curl_errno($curl));
          $response = array(
            'result' => $json_response,


          );
        } else {

          $response = array(
            'response' => $responses,
            'result' => 1,

          );
          $responses['qr'];
          $this->Bu_model->update_qr($nib, $row['id_izin'], $responses['qr']);
        }
        curl_close($curl);
      }
    } else {
      $response = array(
        'response' => $responses,
        'result' => 3,
        'tomorrow' => $tomorrow,
        'now' => $nowx,
        'ss' => $sx

      );
    }

    echo json_encode($response);
  }

