  function post_penilaian($nib, $tgl_permohonan, $record)
  {

    $record_penilaian = $this->Bu_model->berita_acara2_post($nib, $tgl_permohonan);

    $record_2 = $this->Bu_model->token_api_siki();
    $token = $record_2[0]['token'];
    foreach ($record_penilaian as $row) {
      $id_izin = $row['id_izin'];
      $penjualan_tahunan = $row['penjualan_tahunan'];
      $peralatan = $row['peralatan'];
      $smap = $row['smap'];
      $smm = $row['smm'];
      $tk = $row['tk'];
      $aset = $row['aset'];
      $id_asesor = $row['id_asesor'];
      $id1 = encrypt_url($row['NIB']);
      $id2 = encrypt_url($row['id_sub_klasifikasi']);
      $link_penilaian = base_url('sertifikasi/pelaporan_penilaian_lpjk/' . $id1 . '/' . $id2);


      $url = "https://siki.pu.go.id/siki-api/v1/asesor-lsbu-penilaian/$id_izin";
      $curl = curl_init($url);
      curl_setopt($curl, CURLOPT_CUSTOMREQUEST, "POST");
      curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 0);
      curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);
      curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
      curl_setopt($curl, CURLOPT_HTTPHEADER, array(
        "Content-type: application/json",
        "token: $token"
      ));

      $postData = [
        "id_asesor" => "$id_asesor",
        "penjualan_tahunan" => "$penjualan_tahunan",
        "keuangan" => "$aset",
        "tenaga_kerja" => "$tk",
        "peralatan" => "$peralatan",
        "smm" => "1",
        "smap" => "$smap",
        "catatan" => ".",
        "url_formulir_abujk" => "$link_penilaian"
      ];
      curl_setopt($curl, CURLOPT_POSTFIELDS, json_encode($postData));

      $json_response = curl_exec($curl);
      $responses = json_decode($json_response, true);
      $status = curl_getinfo($curl, CURLINFO_HTTP_CODE);
      if ($status != 200) {
        //die("Error: call to URL $url failed with status $status, response $json_response, curl_error " . curl_error($curl) . ", curl_errno " . curl_errno($curl));
        $data = "Failed";
      } else {
        $data = "Success";
      }
      curl_close($curl);
      //echo json_encode($responses);
    }
  }
