      $bulan_romawi = $this->getBulanrw($bulan);
      $panjang = strlen($rec[0]['no_urut']);
      $jumlah = 5 - $panjang;
      $nol = '';
      for ($i = 0; $i < $jumlah; $i++) {
        $nol = $nol . '0';
      }
      $no_surat_evaluator = $nol . $rec[0]['no_urut'] . '/SPK/' . $bulan_romawi . '/' . $tahun;
      $no_surat_pemutus = $nol . $rec[0]['no_urut'] . '/SPK/' . $bulan_romawi . '/' . $tahun;

      $this->post_penunjukan($nib, $tgl_permohonan, $record);
      $this->post_penilaian($nib, $tgl_permohonan, $record);
      $komite_nama = $komite_1 . ', ' . $komite_2 . ', ' . $komite_3;

      $recordv = $this->Bu_model->token_api_siki();
      $token = $recordv[0]['token'];

      foreach ($record as $row) {
        $id1 = encrypt_url($row['NIB']);
        $id2 = encrypt_url($row['id_sub_klasifikasi']);
        $link_surat_tugas_the = base_url('sertifikasi/surat_tugas_fthep_lpjk/' . $id1 . '/' . $id2);
        $link_file_the = base_url('sertifikasi/fthep_cetak_lpjk/' . $id1 . '/' . $id2);

        $id_izin = $row['id_izin'];
        $hasil = $this->security->xss_clean(trim($post['result' . $row['id_sub_klasifikasi']]));
        $peralatan = $this->security->xss_clean(trim($post['peralatan' . $row['id_sub_klasifikasi']]));
        $penjualan_tahunan = $this->security->xss_clean(trim($post['penjualan_tahunan' . $row['id_sub_klasifikasi']]));
        $smm = "1";
        $smap = $this->security->xss_clean(trim($post['smap' . $row['id_sub_klasifikasi']]));

        $data_fthep = $this->Bu_model->penilaian_fthep2($id_izin);
        $user_fthep = $this->Bu_model->get_user($data_fthep[0]['id_asesor']);
        $nama_fthep = $user_fthep[0]['Nama'];


        //EVALUATOR
        $url = "https://siki.pu.go.id/siki-api/v1/lsbu-evaluasi-rekomendasi/$id_izin";
        $curl = curl_init($url);
        curl_setopt($curl, CURLOPT_CUSTOMREQUEST, "POST");
        curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 0);
        curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);
        curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($curl, CURLOPT_HTTPHEADER, array(
          "Content-type: application/json",
          "token: $token"
        ));

        $postData = [
          "nomor_surat_tugas" => "$no_surat_evaluator",
          "nama_anggota_tim_evaluasi" => "$nama_fthep",
          "hasil_evaluasi" => "$hasil",
          "catatan" => ".",
          "url_file_surat_tugas" => "$link_surat_tugas_the",
          "url_formulir_hasil_pelaksanaan_tinjauan_evaluasi" => "$link_file_the"

        ];
        curl_setopt($curl, CURLOPT_POSTFIELDS, json_encode($postData));

        $json_response = curl_exec($curl);
        $responses = json_decode($json_response, true);
        $status = curl_getinfo($curl, CURLINFO_HTTP_CODE);
        $status = 200;
        if ($status != 200) {
          die("Error: call to URL $url failed with status $status, response $json_response, curl_error " . curl_error($curl) . ", curl_errno " . curl_errno($curl));

          $data = "Failed";
        } else {
          $data = "Success";
        }
        curl_close($curl);
        //PEMUTUS
        $url = "https://siki.pu.go.id/siki-api/v1/pemutus-lsbu-keputusan/$id_izin";
        $curl = curl_init($url);
        curl_setopt($curl, CURLOPT_CUSTOMREQUEST, "POST");
        curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 0);
        curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);
        curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($curl, CURLOPT_HTTPHEADER, array(
          "Content-type: application/json",
          "token: $token"
        ));
        $komtek = $this->Bu_model->get_penunjukan_komite_teknis($row['NIB'], $row['tgl_permohonan']);

        $id1 = encrypt_url($row['NIB']);
        $id2 = encrypt_url($row['id_sub_klasifikasi']);
        $link_surat_tugas_komtek = base_url('sertifikasi/surat_tugas_hekt_lpjk/' . $id1 . '/' . $id2);
        $link_file_komtek = base_url('sertifikasi/hekt_cetak_lpjk/' . $id1 . '/' . $id2);
        $tgl_surat_komite = $komtek[0]['tgl_update'];
        $tgl_surat = date("Y-m-d", strtotime($tgl_surat_komite));


        $postData = [
          "nomor_surat_tugas" => "$no_surat_pemutus",
          "nama_anggota_tim_pemutus" => "$komite_nama",
          "keputusan" => "$hasil",
          "catatan" => ".",
          "tanggal_surat_tugas" => "$tgl_surat",

          "daftar_nama_anggota_tim_pemutus" => [$komtek[0]['Nama'], $komtek[1]['Nama'], $komtek[2]['Nama']],
          "url_file_surat_tugas" => "$link_surat_tugas_komtek",
          "url_formulir_hasil_evaluasi_rekomendasi_pemutus" => "$link_file_komtek"

        ];
        curl_setopt($curl, CURLOPT_POSTFIELDS, json_encode($postData));

        $json_response = curl_exec($curl);
        $responses = json_decode($json_response, true);
        $status = curl_getinfo($curl, CURLINFO_HTTP_CODE);

        if ($status != 200) {
          die("Error: call to URL $url failed with status $status, response $json_response, curl_error " . curl_error($curl) . ", curl_errno " . curl_errno($curl));

          $data = "Failed";
        } else {
          $data = "Success";
        }
        curl_close($curl);



        $data = array(
          'pemutus' => $hasil,
          'pemenuhan_peralatan' => $peralatan,
          'pemenuhan_penjualan_tahunan' => $penjualan_tahunan,
          'pemenuhan_smm' => $smm,
          'pemenuhan_smap' => $smap
        );
        $where = array(
          'NIB' => $nib,
          'tgl_permohonan' => $tgl_permohonan,
          'id_sub_klasifikasi' => $row['id_sub_klasifikasi']
        );
        $table = "lsbu_asesor_penilaian";
        $this->Bu_model->update_edit($where, $table, $data);
      }
      $this->Bu_model->pemutus_update($nib, $tgl_permohonan);
      $select = "REPLACE INTO lsbu_komite_teknis (NIB,tgl_permohonan,komite_1,komite_2,komite_3) VALUES ('$nib','$tgl_permohonan','$komite_1','$komite_2','$komite_3')";
      $where = "";
      $this->Bu_model->delete_opr($select, $where);

      $response = array(
        'status' => 1,

      );

      echo json_encode($response);
    }
  }
