        $nama_bu = $nama[0]['Nama'];
        $npwp = $nama[0]['NPWP'];

        $id_asosiasi_lpjk = $this->session->userdata('id_asosiasi');

        $aso = $this->Bu_model->asosiasi_search($id_asosiasi);
        $aso_lpjk = $this->Bu_model->asosiasi_search($id_asosiasi_lpjk);

