        $notiflpjk = $this->notif_lpjk($npwp, $nama_bu, $aso_lpjk[0]['Nama'], $tgl_permohonan, $text_lpjk, $status_lpjk);
        if ($propinsi_lpjk == '00') {
          $pds = '2';
        } else {
          $pds = '1';
        }
        $data = array(
          'ID_GROUP' => $id_group,
          'ID_PDS' => $pds,
          'ID_ASOSIASI' => $id_asosiasi,
