  function search_cabut()
  {
    $post = $this->input->post();
    $input = $this->security->xss_clean(trim($post['input']));
    $option = $this->security->xss_clean(trim($post['option']));
    $data_rec = $this->Bu_model->get_search_cabut($input, $option);
    $record = array();
    foreach ($data_rec as $row) {

      $datax = array(
        'nama' => $row['nama'],
        'NIB' => $row['NIB'],
        'tgl_permohonan' => $row['tgl_permohonan'],
        'id_sub_klasifikasi' => $row['id_sub_klasifikasi'],
        'id_izin' => $row['id_izin'],
        'nib_dec' => encrypt_url($row['NIB']),
        'tgl_dec' => encrypt_url($row['tgl_permohonan']),
      );
      array_push($record, $datax);
    }

    $data = array(
      'record' => $record
    );
    echo json_encode($data);
  }
