  function get_bill($id_bu, $asosiasi, $tgl)
  {

    $record_get = $this->Bu_model->get_jenis($id_bu);
    $id_jenis_bu_kbli = $record_get[0]['ID_Jenis_BU_kbli'];
    $id_bentuk_bu = $record_get[0]['ID_Bentuk_BU'];
    if ($id_jenis_bu_kbli == '0') {
      $id_jenis = 'BU0';
    } elseif ($id_jenis_bu_kbli == '5') {
      $id_jenis = 'BU5';
    } else {
      $id_jenis = 'BU1';
    }

    if ($id_bentuk_bu == '3') {
      $id_asing = '1';
    } else {
      $id_asing = '0';
    }

    $record = $this->Bu_model->get_bill($id_bu, $asosiasi, $tgl, $id_jenis, $id_asing);
    return $record;
  }


  function getBulan($bln)
  {
    switch ($bln) {
      case 1:
        return "Januari";
        break;
      case 2:
        return "Februari";
        break;
      case 3:
        return "Maret";
        break;
      case 4:
        return "April";
        break;
      case 5:
        return "Mei";
        break;
      case 6:
        return "Juni";
        break;
      case 7:
        return "Juli";
        break;
      case 8:
        return "Agustus";
        break;
      case 9:
        return "September";
        break;
      case 10:
        return "Oktober";
        break;
      case 11:
        return "November";
        break;
      case 12:
        return "Desember";
        break;
    }
  }
  function getBulanrw($blnrw)
  {
    switch ($blnrw) {
      case 1:
        return "I";
        break;

      case 2:
        return "II";
        break;

      case 3:
        return "III";
        break;

      case 4:
        return "IV";
        break;
      case 5:
        return "V";
        break;

      case 6:
        return "VI";
        break;

      case 7:
        return "VII";
        break;

      case 8:
        return "VIII";
        break;

      case 9:
        return "IX";
        break;

      case 10:
        return "X";
        break;

      case 11:
        return "XI";
        break;

      case 12:
        return "XII";
        break;
    }
  }

